#!/usr/bin/env node
// O-38: golden numbers for the bodies of the tonic sphere. The lab page (docs/design/lab2/orbs.js) is the
// reference; this runs its thread and sand through a recording stand-in for WebGL and writes what they would have
// sent to the GPU. core:music's ThreadBody and SandBody are tested against it (OrbBodiesTest).
//
//   node scripts/orb_golden.js > core/music/src/test/resources/orb-golden.txt
//
// Do not edit the file by hand: change the script (or the lab page) and run it again.
'use strict';
const fs = require('fs');
const path = require('path');
const src = fs.readFileSync(path.join(__dirname, '..', 'docs', 'design', 'lab2', 'orbs.js'), 'utf8');
// the page is an IIFE that hangs OrbLab2 on `window` or, here, on globalThis
(0, eval)(src);
const Lab = globalThis.OrbLab2;

/** A WebGL that accepts everything and keeps what is sent to bufferSubData. */
function fakeCanvas(captured) {
  const gl = new Proxy({}, {
    get(_, name) {
      if (name === 'bufferSubData') return (_t, _o, data) => captured.push(Float32Array.from(data));
      if (name === 'getShaderParameter') return () => true;
      if (name === 'getProgramParameter') return (_p, what) => (what === 'ACTIVE_UNIFORMS' ? 0 : true);
      if (name === 'getExtension') return () => ({});
      if (typeof name === 'string' && /^[A-Z0-9_]+$/.test(name)) return name; // constants: any distinct value
      return () => ({});
    },
  });
  return { width: 300, height: 300, getContext: () => gl };
}

const DT = 1 / 60;

// ---- thread: a pluck, then an answer (a fifth), a tense one (a minor second), and a clear
function thread() {
  const cap = [];
  const orb = Lab.makers.thread(fakeCanvas(cap));
  const script = [[6, 'pluck'], [120, 'answer7'], [400, 'answer1'], [600, 'clear']];
  const shots = [5, 20, 60, 119, 125, 150, 240, 300, 410, 480, 599, 640, 700];
  const idx = [0, 400, 800, 1600, 2400, 3200];
  const frames = [];
  let si = 0;
  for (let f = 1; f <= shots[shots.length - 1]; f++) {
    if (si < script.length && f === script[si][0]) {
      const e = script[si++][1];
      if (e === 'pluck') orb.pluck(1, 0.3, -0.7);
      if (e === 'answer7') orb.answer(7);
      if (e === 'answer1') orb.answer(1);
      if (e === 'clear') orb.clear();
    }
    cap.length = 0;
    orb.step(DT);
    if (shots.includes(f)) {
      const data = cap[0]; // one bufferSubData per frame: the ribbon
      frames.push({ frame: f, points: idx.map(i => [data[i * 14], data[i * 14 + 1], data[i * 14 + 4]]) });
    }
  }
  return { dt: DT, script: script.map(([f, e]) => ({ frame: f, event: e })), indices: idx, frames };
}

// ---- sand: a pluck, an answer (a fifth), a clear
function sand() {
  const cap = [];
  const N = 3000;
  const orb = Lab.makers.sand(fakeCanvas(cap), N);
  const script = [[30, 'pluck'], [90, 'answer7'], [320, 'clear']];
  const shots = [1, 29, 60, 100, 150, 300, 330, 400];
  const idx = [0, 1, 7, 100, 999, 2999];
  const frames = [];
  let si = 0;
  for (let f = 1; f <= shots[shots.length - 1]; f++) {
    if (si < script.length && f === script[si][0]) {
      const e = script[si++][1];
      if (e === 'pluck') orb.pluck(1);
      if (e === 'answer7') orb.answer(7);
      if (e === 'clear') orb.clear();
    }
    cap.length = 0;
    orb.step(DT);
    if (shots.includes(f)) {
      const data = cap[0]; // the grains: x, y, heat
      frames.push({ frame: f, grains: idx.map(i => [data[i * 3], data[i * 3 + 1], data[i * 3 + 2]]) });
    }
  }
  return { dt: DT, count: N, script: script.map(([f, e]) => ({ frame: f, event: e })), indices: idx, frames };
}

// plain lines, so that the test needs no parser:  body <name> / event <frame> <what> / index <i...> / frame <n> <numbers...>
function dump(name, b, key) {
  const out = ['body ' + name, 'dt ' + b.dt];
  for (const e of b.script) out.push('event ' + e.frame + ' ' + e.event);
  out.push('index ' + b.indices.join(' '));
  for (const f of b.frames) out.push('frame ' + f.frame + ' ' + f[key].flat().join(' '));
  return out.join('\n');
}
process.stdout.write('# generated by scripts/orb_golden.js from docs/design/lab2/orbs.js\n' + dump('thread', thread(), 'points') + '\n' + dump('sand', sand(), 'grains') + '\n');
